package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamAbhinayaRasaBank2 {
    private const val T = "නාට්‍ය ශාස්ත්‍රය, චතුර්විධ අභිනය හා නව රසය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("නාට්‍ය ශාස්ත්‍රයේදී සඳහන් වන 'රසෝත්පත්තිය' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "ප්‍රේක්ෂක සිත තුළ සෞන්දර්ය වින්දනය හටගැනීම", "වේදිකාව මත බෙර පද තාලය මාරු කිරීම", "නැට්ටුවාගේ රංග වස්ත්‍ර හා ආභරණ සැකසීම", "ශාලාවේ ආලෝක පහන් වර්ණ වෙනස් කිරීම", "නිර්මාණකරුගේ භාවයන් ප්‍රේක්ෂකයා තුළ රසයක් බවට පත්වීම රසෝත්පත්තියයි."),
        q("නව රසයෙහි 'විභාව, අනුභාව සහ ව්‍යභිචාරී භාව' එක් වූ විට උපදින්නේ කුමක්දැයි භරත මුනිවරයා දැක්වීද?", "රසය", "තාලය", "වන්නම", "සරඹය", "'විභාවානුභාව ව්‍යභිචාරී සංයෝගාත් රස නිෂ්පත්ති:' යනු නාට්‍ය ශාස්ත්‍රයේ ප්‍රධාන සූත්‍රයයි."),
        q("යම් රසයක් හට ගැනීමට මුල් වන පුද්ගලයා හෝ පරිසර හේතුව නාට්‍ය ශාස්ත්‍රයේ හඳුන්වන්නේ කුමන නමකින්ද?", "විභාව", "අනුභාව", "ආහාර්ය", "තානම", "හැඟීම් උපදවන මූලික හේතුව (ආලම්බන හා උද්දීපන) විභාව ලෙස හැඳින්වේ."),
        q("හැඟීමක් ඇති වූ පසු ශරීරයෙන් පිටතට පෙනෙන ඇහිබැම එසවීම, බැල්ම හා අත් චලන ආදිය හඳුන්වන්නේ කෙසේද?", "අනුභාව", "විභාව", "සංචාරී භාව", "වාචික", "අභ්‍යන්තර හැඟීම බාහිරට පෙන්වන ශාරීරික ප්‍රතික්‍රියා අනුභාව වේ."),
        q("චතුර්විධ අභිනය අතරින් 'වාචික අභිනය' සම්පූර්ණයෙන්ම ඉවත් කර රඟදක්වන නර්තන අංගයක් කුමක්ද?", "මුද්‍රා නාට්‍ය හා නිහඬ නර්තන හරඹ", "සාම්ප්‍රදායික වන්නම් කවි ගායනය", "පහතරට සන්නි යකුමේ විකට සංවාද", "ගැමි සොකරි නාටකයේ කථා දෙබස්", "කතාව හා දෙබස් නොමැතිව සංගීතය හා චලන මගින් කතාව කීමේදී ආංගික අභිනය ප්‍රමුඛ වේ."),
        q("දේශීය නර්තනයේ 'ආහාර්ය අභිනය' වඩාත් දියුණු ලෙස යොදාගෙන ඇති ප්‍රධාන සම්ප්‍රදායික කලාව කුමක්ද?", "උඩරට වෙස් ඇඳුම සහ පහතරට වෙස්මුහුණු", "සරල සරඹ අභ්‍යාස සුදු ඇඳුම", "පාසල් සිසුන්ගේ දෛනික නිල ඇඳුම", "සාමාන්‍ය ගැමි පුහුණු සරම හා කමිසය", "ඇඳුම් පැළඳුම් හා වෙස් ගැන්වීම මගින්ම චරිතය හඳුනාගැනීමට ඉඩ සැලසීම ආහාර්ය අභිනයයි."),
        q("නර්තන කලාවේදී 'නෘත්ත' කොටස් නැටීමේදී ප්‍රධාන වශයෙන්ම කැපී පෙනෙන අංගය කුමක්ද?", "පාද චලන, තාලය, ලය හා අලංකාර ශරීර හැඩතල", "දීර්ඝ කථා පුවතක් කීම", "විකට දෙබස් කීම", "බිම හිඳගෙන ඇඬීම", "කතාවක් නොකියා රිද්මයේ අලංකාරය පමණක් දැක්වීම නෘත්තයේ ස්වභාවයයි."),
        q("අෂ්ට සාත්වික භාව අතරින් 'අශ්‍රැ' යනුවෙන් හඳුන්වන්නේ කුමන ස්වාභාවික ලක්ෂණයද?", "දැඩි දුක හෝ ප්‍රීතිය නිසා ඇස්වලින් කඳුළු ගැලීම", "ශරීරය දහඩිය දැමීම", "රෝම කූප කෙළින් වීම", "කටහඬ වෙනස් වීම", "සැබෑ භාවමය ගැඹුර ප්‍රේක්ෂකයාට දැනෙන ප්‍රබල සාත්වික අංගයකි."),
        q("අෂ්ට සාත්වික භාව අතුරින් 'රෝමාංච' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "පුදුමය, භක්තිය හෝ බිය නිසා ඇඟේ ලොම් කෙළින් වීම", "දැඩි කෝපය නිසා මුහුණේ පැහැය රතු වීම", "තැතිගැන්ම නිසා දෙඅත් හා දණහිස් නැවීම", "ශෝකය ඉවසිය නොහැකිව වේදිකාව මත වැටීම", "අභ්‍යන්තර හැඟීමේ ප්‍රබලත්වය නිසා ශරීරයේ හටගන්නා ස්වාභාවික ප්‍රතිචාරයකි."),
        q("අෂ්ට සාත්වික භාව අතුරින් 'ස්වේද' යනු කුමක්ද?", "භය, ලැජ්ජාව හෝ ආවේගය නිසා සිරුරෙන් දහඩිය දැමීම", "කිසිදු චලනයක් නොදක්වා ගලක් මෙන් නිශ්චල වීම", "හැඟීම් උද්දීපනය වීම නිසා වචන පිට නොවී සිටීම", "සතුට ඉවසිය නොහැකිව උස් හඬින් සිනහසෙමින් සිටීම", "මානසික ආතතිය හෝ උද්යෝගය නිසා හටගන්නා කායික ලක්ෂණයකි."),
        q("නාට්‍ය ශාස්ත්‍රයේ 'ග්‍රීවා භේද' අතරින් 'සුන්දරී' යන බෙල්ල චලනය කරන ආකාරය කුමක්ද?", "හිස කෙළින් තබා බෙල්ල තිරස්ව දෙපසට මෘදුව ලිස්සවා චලනය කිරීම", "බෙල්ල ඉදිරියට හා පසුපසට වේගයෙන් ගැසීම", "බෙල්ල වටේට කරකැවීම", "බෙල්ල පහළට නවාගෙන සිටීම", "භාරතීය හා දේශීය ලාස්‍ය නර්තනවල අලංකාරය වැඩි කිරීමට සුන්දරී ග්‍රීවා භේදය යොදයි."),
        q("නර්තනයේදී හිස දකුණට හා වමට ප්‍රතික්ෂේප කිරීමේ අර්ථයෙන් සෙලවීම කුමන ශිරෝ භේදයද?", "ධුත ශිරෝ භේදය", "සම ශිරෝ භේදය", "උද්වාහිත ශිරෝ භේදය", "අධෝමුඛ ශිරෝ භේදය", "'නැත', 'එපා', 'අසම්මතයි' යන අදහස් දැක්වීමට ධුත ශිරෝ භේදය භාවිත කෙරේ."),
        q("හිස ඉහළ පහළ සොලවා 'ඔව්' හෝ 'එකඟ වීම' ප්‍රකාශ කරන ශිරෝ භේදය කුමක්ද?", "කම්පිත ශිරෝ භේදය", "ධුත ශිරෝ භේදය", "අංචිත ශිරෝ භේදය", "නික්ෂිප්ත ශිරෝ භේදය", "කෝපය, තර්ජනය හෝ ස්ථිරව එකඟ වීම පෙන්වීමට කම්පිත භේදය යොදා ගනී."),
        q("දෑස් හා බැල්ම පිළිබඳ 'සම දෘෂ්ටිය' යොදා ගනු ලබන්නේ කුමන අවස්ථාවකදීද?", "නැටුම ආරම්භයේදී, සාමාන්‍ය ස්වභාවයේදී හා දේව රූප නිරූපණයේදී", "තද කෝපයෙන් සතුරෙකු දෙස බලන විට", "ලැජ්ජාවෙන් ඇස් ඉවතට ගන්නා විට", "විකට රංගනයකදී", "ඇහිබැම නොසොල්වා කෙළින් ඉදිරිය බලා සිටීම සම දෘෂ්ටියයි."),
        q("රෞද්‍ර හා වීර රසයන්හිදී 'තාණ්ඩව නර්තනය' යොදාගන්නා අතර, ශෘංගාර හා කරුණා රසයන්හිදී යොදාගන්නා ශෛලිය කුමක්ද?", "ලාස්‍ය ශෛලිය", "තාණ්ඩව ශෛලිය", "කෝලම් ශෛලිය", "සන්නි ශෛලිය", "මෘදු ලාලිත්‍යමය චලන ශෘංගාර හා කරුණා රසයන් තීව්‍ර කරයි."),
        q("නව රස අතුරින් 'කරුණා රසය' මතු වන දේශීය නර්තන හෝ ගායන අවස්ථාවකට උදාහරණයක් කුමක්ද?", "කොහොඹා කංකාරියේ කුවේණි අස්න හෝ සද්ධන්ත කවි ගායනය", "හේවා කෝලමේ විකට සටන", "ගජගා වන්නමේ කස්තිරම", "රබන් කරකැවීම", "කුවේණියගේ විලාපය ඇතුළත් පුවත් ප්‍රේක්ෂකයා තුළ ශෝකය හා අනුකම්පාව දනවයි."),
        q("නව රස අතුරින් 'අද්භූත රසය' පහතරට හා උඩරට නැටුම්වලදී බොහෝ විට මතු වන්නේ කුමන අවස්ථාවකදීද?", "දුම්මල ගසා ගිනි ජාලා මැවීමේදී හා ගිනි පෑගීමේදී", "පා සරඹ පළමු පාඩමේදී", "ලී කෙළි ගැසීමේදී", "වී පෙළීමේදී", "සාමාන්‍ය මිනිස් හැකියාව ඉක්මවන දර්ශන තුළින් ප්‍රේක්ෂකයා තුළ විස්මය ඇති වේ."),
        q("නර්තනයේදී 'වේදිකා අවකාශය' හා 'ආලෝකකරණය' භාවිත කිරීම අයත් වන්නේ කවර අභිනයටද?", "ආහාර්ය අභිනයට", "වාචික අභිනයට", "ආංගික අභිනයට", "සාත්වික අභිනයට", "රංගනයේ පසුබිම් පරිසරය හා දෘශ්‍ය භාවයන් නිමවීම ආහාර්ය අභිනයේ කොටසකි."),
        q("'නාට්‍ය ශාස්ත්‍රය' ග්‍රන්ථයට අනුව 'වචන, කවි හා සංගීත ස්වර' එක් වූ විට පෝෂණය වන අභිනය කුමක්ද?", "වාචික අභිනය", "ආහාර්ය අභිනය", "ආංගික අභිනය", "සාත්වික අභිනය", "රංගනයක ශබ්ද හා භාෂාමය ප්‍රකාශනය වාචික අභිනයෙන් සම්පූර්ණ වේ."),
        q("පෙරදිග නර්තනයේ 'ශිරෝ භේද' අතර හිස මඳක් පැත්තකට ඇල කර සුන්දර ලෙස තබා ගැනීම හඳුන්වන්නේ කෙසේද?", "අංචිත ශිරෝ භේදය", "සම ශිරෝ භේදය", "ධුත ශිරෝ භේදය", "උද්වාහිත ශිරෝ භේදය", "ප්‍රේමය, සිතුවිලි බව හෝ විලාසිතාව පෙන්වීමට අංචිත හිස භාවිත කරයි."),
        q("භාරතීය 'නව රස' සංකල්පය ශ්‍රී ලංකාවේ නර්තන විෂය මාලාවට ඇතුළත් කර ඇත්තේ ඇයි?", "නැටුමක භාවමය හා සෞන්දර්ය ගුණය විද්‍යාත්මකව හඳුනාගෙන රසවිඳීමට", "සියලු දේශීය නැටුම් අත්හැරීමට", "සංගීතය නතර කිරීමට", "ඇඳුම් මැසීමට", "රස සිද්ධාන්තය ඕනෑම පෙරදිග කලා නිර්මාණයක් ඇගයීමට පොදු මිනුම් දණ්ඩකි."),
        q("වීර රසය ප්‍රධාන වන උඩරට නැටුම් අංගයක් හෝ වන්නමක් කුමක්ද?", "සිංහරාජ වන්නම සහ ඊරඩි වන්නම", "මුසලඩි වන්නම", "හනුමා වන්නම", "කළගෙඩි නැටුම", "සිංහයාගේ තේජස හා රණකාමී බව මෙම වන්නම් තුළ වීර රසයෙන් ඉදිරිපත් වේ."),
        q("හාස්‍ය රසය ප්‍රධාන වන දේශීය නර්තන අංගයකට උදාහරණයක් කුමක්ද?", "කෝලම් නාට්‍යයේ ජසයා සහ ලෙන්චිනා", "අසදිස වන්නම", "මඟුල් බෙර වාදනය", "මල් පූජා නැටුම", "විකට දෙබස් හා අභිනයන් නිසා ජසයා හා ලෙන්චිනා හාස්‍ය රසය උපදවයි."),
        q("නාට්‍ය ශාස්ත්‍රයේදී 'ශාන්ත රසය' මූලික රස අටට පසු කාලීනව එකතු කළ මුඛ්‍ය විද්වතා හෝ ග්‍රන්ථය කුමක්ද?", "උද්භට හා අභිනවගුප්ත වැනි පසුකාලීන අලංකාරිකයන් විසින්", "පෘතුගීසි නාවිකයන් විසින්", "නූතන සිනමාකරුවන් විසින්", "ග්‍රීක දාර්ශනිකයන් විසින්", "බෞද්ධ හා භාරතීය චින්තන ආභාසයෙන් ශාන්ත රසය නවවන රසය ලෙස පිළිගැනිණි."),
        q("නර්තනයකදී 'ආංගික අභිනය' ප්‍රධාන අංග තුනක් ඔස්සේ ක්‍රියාත්මක වේ. ඒවා මොනවාද?", "අංග, ප්‍රත්‍යංග සහ උපාංග", "රතු, කහ සහ නිල්", "කවි, ගී සහ තානම්", "දවුල, බෙරය සහ රබාන", "හිස-අත්-පා (අංග), උර-වැලමිට-දණ (ප්‍රත්‍යංග) සහ ඇස්-තොල්-ඇහිබැම (උපාංග) ලෙස බෙදේ."),
        q("'උපාංග' යන කාණ්ඩයට අයත් වන සියුම් අභිනය සඳහා භාවිත වන ශරීර කොටස් මොනවාද?", "ඇස්, ඇහිබැම, කම්මුල්, නාසය සහ තොල්", "කලවා සහ කෙණ්ඩා", "උරහිස් සහ පිටුපස", "පාදයේ විළුඹ", "මුහුණේ සියුම් ඉරියව් වෙනස් කර හැඟීම් ප්‍රකාශ කිරීමට උපාංග උපකාරී වේ."),
        q("දෘෂ්ටි භේද අතරින් 'සාචි දෘෂ්ටිය' (වැලි ඇසින් හෙවත් ඇස් කොණින් බැලීම) පෙන්වන්නේ කුමන භාවයක්ද?", "ලැජ්ජාව, සැකය, රහස් කීම හෝ ශෘංගාරය", "තද නින්ද", "සිහි මුර්ජා වීම", "කන් ඇසීම", "ඇස් කොණින් මෘදුව බැලීම සාචි දෘෂ්ටිය නම් වන අතර එය ප්‍රේම හා කුතුහල භාවයන් පෙන්වයි."),
        q("නව රස අතුරින් 'රෞද්‍ර රසයේ' අධිපති දෙවියා ලෙස සාම්ප්‍රදායිකව සලකන්නේ කවුද?", "රුද්‍ර හෙවත් ශිව දෙවියන්", "බ්‍රහ්ම දෙවියන්", "විෂ්ණු දෙවියන්", "ඉන්ද්‍ර දෙවියන්", "විනාශකාරී කෝපය හා බලය රුද්‍ර දෙවියන්ගෙන් සංකේතවත් කෙරේ."),
        q("නව රස අතුරින් 'කරුණා රසයේ' අධිපති දෙවියා ලෙස සලකන්නේ කවුරුන්ද?", "යම දෙවියන්", "විෂ්ණු දෙවියන්", "ප්‍රමථ ගණ", "ශක්‍ර දෙවියන්", "වියෝව හා ශෝකී හැඟීම යම දෙවියන් හා සම්බන්ධ කර දක්වා ඇත."),
        q("නර්තනයේදී 'අනුකරණය' යන ගුණාංගය හා 'අභිනය' අතර ඇති සම්බන්ධතාව කුමක්ද?", "ලෝකයේ ස්වභාවයන් නර්තන නියමයන් අනුව කලාත්මකව අනුකරණය කිරීම අභිනයයි", "දෙක අතර කිසිදු සම්බන්ධයක් නැත", "අභිනය ඇති විට අනුකරණය තහනම් වේ", "අනුකරණය යනු පොත් පිටපත් කිරීමයි", "නාට්‍යය යනු ත්‍රෛලෝක්‍ය භාවානුකීර්තනයක් බව නාට්‍ය ශාස්ත්‍රයේ කියැවේ."),
        q("චතුර්විධ අභිනයන් අතුරින් ප්‍රේක්ෂකයාට ප්‍රථමයෙන්ම පෙනී යන බාහිර අභිනය කුමක්ද?", "ආහාර්ය අභිනය (වේදිකාව, ආලෝකය හා ඇඳුම්)", "සාත්වික අභිනය", "වාචික අභිනය", "මුද්‍රා අභිනය", "නැට්ටුවා කතා කිරීමට හෝ නැටීමටත් පෙර ඇඳුමින් හා වේෂ නිරූපණයෙන් චරිතය හඳුනාගැනේ."),
        q("නර්තන රංගනයකදී 'භාව' හා 'රස' අතර ඇති හේතුඵල සම්බන්ධතාව කුමක්ද?", "ශිල්පියා විසින් ප්‍රකාශ කරන 'භාවයන්' නිසා රසිකයා තුළ 'රසය' උපදී", "රසිකයාගේ රස වින්දනය නිසා බෙර හඬ සම්පූර්ණයෙන්ම නැති වී යයි", "කිසිදු භාව නිරූපණයක් නොමැතිව රසය ප්‍රේක්ෂකයා තුළ ඉබේ උපදී", "භාවය හා රසය යනු කිසිදා එක්ව නොයන ප්‍රතිවිරුද්ධ සංකල්ප දෙකකි", "භාවය හේතුව වන අතර රසය එහි සෞන්දර්යාත්මක ඵලයයි."),
        q("දේශීය නර්තන අංගයක් වන 'කළගෙඩි නැටුම' තුළ ප්‍රමුඛව දිස්වන රසය කුමක්ද?", "ශෘංගාර හා ප්‍රීතිමත් සෞම්‍ය රසය", "රෞද්‍ර රසය", "භයානක රසය", "භීභත්ස රසය", "ගැමි ලියන්ගේ සතුට, අලංකාරය හා ලාලිත්‍යය මෙහි කැපී පෙනේ."),
        q("පහතරට 'මහ සොහොන් සමයමේදී' ප්‍රේක්ෂකයා තුළ ප්‍රධාන වශයෙන් ජනිත වන රසය කුමක්ද?", "භයානක හා අද්භූත රසය", "ශාන්ත රසය", "ශෘංගාර රසය", "කරුණා රසය", "රාත්‍රී පන්දම් එළිය හා රෞද්‍ර වෙස්මුහුණ තැතිගැන්ම හා විස්මය ඇති කරයි."),
        q("නර්තන ශිල්පියෙකු 'මුහුණු අභිනය' ප්‍රගුණ කිරීමෙන් ලැබෙන ප්‍රධාන වාසිය කුමක්ද?", "වචන නොපවසාම ඕනෑම හැඟීමක් ප්‍රේක්ෂකයාට සමීප කරවීමට හැකි වීම", "පාද චලන අවශ්‍ය නොවීම", "වෙස්මුහුණු පැළඳීමට පහසු වීම", "වේගයෙන් දිවීමට හැකි වීම", "ඇස්, ඇහිබැම හා තොල්වල සියුම් චලන නර්තනයට ජීවය දෙයි."),
        q("'භරත මුනිවරයා' විසින් නාට්‍ය කලාව නිර්මාණය කිරීමේදී 'අභිනය' ලබාගත්තේ කුමන වේදයෙන් බව පුරාවෘත්තයේ සඳහන් වේද?", "යජුර් වේදයෙන්", "සාම වේදයෙන්", "ඍග් වේදයෙන්", "අථර්ව වේදයෙන්", "ඍග් වේදයෙන් පාඨ්‍යයද, සාම වේදයෙන් ගීතද, යජුර් වේදයෙන් අභිනයද, අථර්ව වේදයෙන් රසයද ගත්තේය."),
        q("'නාට්‍ය වේදය' හෙවත් පස්වන වේදය බිහි කිරීමේදී 'රසය' ලබා ගත් වේද ග්‍රන්ථය කුමක්ද?", "අථර්ව වේදය", "සාම වේදය", "ඍග් වේදය", "යජුර් වේදය", "සතර වේදයන්ගේ සාරය එක් කොට නාට්‍ය වේදය නිර්මාණය කළ බව නාට්‍ය ශාස්ත්‍රයේ දැක්වේ."),
        q("නාට්‍ය ශාස්ත්‍රයේදී 'ප්‍රකම්පිත' යන ග්‍රීවා භේදයෙන් (බෙල්ල ඉදිරියට හා පසුපසට සෙලවීමෙන්) නිරූපණය කරන්නේ කුමක්ද?", "පරෙවියෙකුගේ ගමන, ප්‍රීතිය හෝ 'හොඳයි' යන හැඟීම", "ගලක් මෙන් නිශ්චල වීම", "බිම වැටීම", "අඬමින් වැළපීම", "උද්යෝගය හා රිද්මමය සෞන්දර්යය මෙම ග්‍රීවා භේදයෙන් ප්‍රකාශ කෙරේ."),
        q("නර්තනයකදී 'තාණ්ඩව' හා 'ලාස්‍ය' යන දෙකම සමබරව යොදා ගැනීමෙන් නිර්මාණයට ලැබෙන්නේ කුමක්ද?", "ශක්තිමත් ජවය හා සෞම්‍ය ලාලිත්‍යය එකවර රසවිඳීම", "නැටුමේ මූලික තාලය හා ලය අක්‍රමවත් වීම", "රංගන රිද්මය ඒකාකාරීව හා හිස්ව පැවතීම", "වාද්‍ය භාණ්ඩ හා නර්තන අංග වෙන් වීම", "උස් පහත් රිද්ම විවිධත්වය ප්‍රේක්ෂක අවධානය රඳවා ගනී."),
        q("පෙරදිග රංග කලාවේදී 'ලෝක ධර්මී' අභිනය යනුවෙන් හඳුන්වන්නේ කුමක්ද?", "සාමාන්‍ය එදිනෙදා ලෝකයේ මිනිසුන් හැසිරෙන ස්වාභාවික තාත්වික රංගනය", "සම්පූර්ණයෙන්ම මුද්‍රා වලින් කරන රංගනය", "අදෘශ්‍යමාන රංගනය", "වෙස්මුහුණු නාට්‍ය පමණක්", "නාට්‍ය ධර්මී හෙවත් ශෛලිගත රංගනයට වඩා තාත්වික ස්වභාවය ලෝක ධර්මී වේ."),
        q("නර්තන කලාවේදී 'නාට්‍ය ධර්මී' අභිනය යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "නිශ්චිත නර්තන නීති, මුද්‍රා හා සංකේතාත්මක රිද්ම මත පදනම් වූ ශෛලිගත රංගනය", "කිසිදු තාලයක් හෝ නීතියක් නොමැතිව එදිනෙදා ක්‍රියාවන් ඒ අයුරින්ම රඟපෑම", "සාමාන්‍ය ජීවිතයේ පාරේ ඇවිදින අයුරින් ස්වාභාවිකව කතාබහ කරමින් ගමන් කිරීම", "කිසිදු ශාරීරික අංග චලනයක් නොදක්වා නිහඬව ආසනයක හිඳ සිටින අවස්ථාව", "උඩරට හා භරත නාට්‍යම් වැනි ශාස්ත්‍රීය නර්තන සම්ප්‍රදායන් නාට්‍ය ධර්මී වේ."),
        q("නව රස අතුරින් 'වීර රසයට' හිමි ස්ථායී භාවය වන 'උත්සාහ' භාවය ප්‍රකට වන්නේ කුමන අවස්ථාවකදීද?", "අසාධාරණයට එරෙහිව නැඟී සිටීම, ත්‍යාගශීලී බව හා ධෛර්යසම්පන්න ක්‍රියාවලදී", "කම්මැලිකමින් නිදා සිටින විට", "බියෙන් පලා යන විට", "අපිරිසිදු දෙයක් දැක පිළිකුල් කරන විට", "දන්දීම, යුද්ධය හා ධර්මය රැකීම වීර රසයේ විවිධ අවස්ථා වේ."),
        q("දෘෂ්ටි භේද අතරින් 'ආලෝකිත' දෘෂ්ටිය යොදා ගන්නේ කවර අවස්ථාවක් නිරූපණයටද?", "ඇස් විශාල කර පුදුමයෙන් යමක් බැලීමට", "නිදිමතින් ඇස් පියවෙන බව පෙන්වීමට", "දුකින් කඳුළු සලන ආකාරය දැක්වීමට", "ඇස් වසා භාවනා කරන ඉරියව්ව පෙන්වීමට", "අලංකාර දර්ශනයක් හෝ පුදුම දෙයක් දුටු විට මෙම බැල්ම යොදයි."),
        q("දේශීය නර්තන කලාවේ 'මුහුණේ වෙස් ගැන්වීම' හෙවත් Make-up සිදු කිරීම අයත් වන්නේ කුමන අභිනයටද?", "ආහාර්ය අභිනයට", "වාචික අභිනයට", "සාත්වික අභිනයට", "ආංගික අභිනයට", "චරිතයේ ස්වභාවය ඉස්මතු කිරීමට සිදු කරන අංග රචනය ආහාර්ය අභිනයේ කොටසකි."),
        q("නර්තනය හා සෞන්දර්ය විද්‍යාව හදාරන සිසුවෙකුට 'නව රස' දැනුම ප්‍රයෝජනවත් වන්නේ ඇයි?", "ඕනෑම නර්තන හෝ නාට්‍ය නිර්මාණයක ගැඹුරු භාවමය අර්ථය විචාරශීලීව අගය කිරීමට", "රංග ශාලාවේ වේදිකා ආලෝකකරණ උපකරණ හා තිර රෙදිවල මිල ගණන් තීරණය කිරීමට", "උඩරට හා පහතරට බෙරවල ඇසට ගව හා එළු සම් පදම් කර තැබීම සිදු කිරීමට", "දහඅට සන්නි හා කෝලම් නැටුම් සඳහා වෙස්මුහුණු ලීයෙන් කැපීමට පමණක් යෙදීමට", "රස වින්දන හැකියාව හා කලා විචාර බුද්ධිය නව රස දැනුමෙන් වර්ධනය වේ."),
        q("නාට්‍ය ශාස්ත්‍රයේදී 'චතුර්විධ අභිනය' අතරින් ශරීර අවයව චලනය පමණක් භාවිත වන අභිනය කුමක්ද?", "ආංගික අභිනය", "වාචික අභිනය", "ආහාර්ය අභිනය", "සාත්වික අභිනය", "අත්, පා, හිස හා මුහුණේ චලන මගින් අර්ථ දැක්වීම ආංගික අභිනයයි."),
        q("'යතෝ භාවස් තතෝ රස:' යන අභිනය දර්පණ ශ්ලෝක කොටසේ නිවැරදි අර්ථය කුමක්ද?", "සැබෑ භාවය පවතින තැන රසය උපදින බව", "රසය නැති තැන බෙර වයන බව", "භාවයෙන් තොරව නැටිය යුතු බව", "රසය යනු ආහාර රස පමණක් බව", "නර්තනයක අවසාන පරමාර්ථය වූ රසෝත්පත්තිය සිදුවන්නේ සැබෑ භාවයෙන් බව මෙයින් කියැවේ."),
        q("නව රස අතරින් 'ශෘංගාර රසයේ' ප්‍රධාන ස්ථායී භාවය වන 'රති' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "ප්‍රේමය, සෙනෙහස සහ සුන්දරත්වය කෙරෙහි ඇති ඇල්ම", "යුද්ධය හා කෝපය කෙරෙහි ඇති උද්වේගය", "මරණ බිය හා තැතිගැන්ම පිළිබඳ හැඟීම", "අපිරිසිදු දෙයක් කෙරෙහි ඇති පිළිකුල", "පෙරදිග සෞන්දර්ය විද්‍යාවේ උසස් ප්‍රේමණීය හැඟීම රති ලෙස හැඳින්වේ."),
        q("දේශීය නර්තනයේ 'තෙල්මේ' හෝ 'ගජගා වන්නම' නටන විට නැට්ටුවාගේ උරමාල, සිළම්බු හා වෙස් තට්ටුව අයත් වන්නේ කුමන අභිනයටද?", "ආහාර්ය අභිනයට", "වාචික අභිනයට", "සාත්වික අභිනයට", "ආංගික අභිනයට", "වෙස් ගැන්වීම හා ආභරණ පැළඳීම ආහාර්ය අභිනය ලෙස සැලකේ."),
        q("රංගනයකදී 'වාචික අභිනය' වැඩි වශයෙන්ම භාවිත වන දේශීය ගැමි නාට්‍ය අංගයක් කුමක්ද?", "සොකරි හා කෝලම් දෙබස් අංග", "පා සරඹ පමණක්", "නිහඬ බැලේ නැටුම", "ගොක් කොළ කැපීම", "කථාව, ගායනය හා උපහාසාත්මක දෙබස් වාචික අභිනය ප්‍රබල කරයි."),
        q("නාට්‍ය ශාස්ත්‍රයට අනුව 'විභාව' යනු කුමක්ද?", "ස්ථායී භාවය අවදි කර රසය උපදවන මූලික හේතු", "රංගනය අවසානයේ පළඳින වේෂ නිරූපණ ආභරණ", "වේදිකාවේ පසුබිම් තිර හා ආලෝක සැරසිලි", "බෙර වාදනය ආරම්භ කරන මූලික තාල රටාව", "චරිත හා පරිසර සාධක විභාව ලෙස හැඳින්වේ."),
        q("'ආලම්බන විභාව' සඳහා උදාහරණයක් කුමක්ද?", "භාවය උපදින ප්‍රධාන චරිත හෝ වස්තුව", "වේදිකාවේ ඉදිරිපස තිරය හා සැරසිලි", "රංග ශාලාවේ ප්‍රේක්ෂක අසුන් පෙළ", "පසුබිම් සංගීතයේ බෙර හඬ පමණක්", "හැඟීම ඇතිවීමට සෘජු අරමුණ වන පුද්ගලයා හෝ වස්තුව ආලම්බන විභාවයි."),
        q("අෂ්ට සාත්වික භාව අතරින් 'රෝමාංච' යන ලක්ෂණය ඇති විය හැකි මානසික අවස්ථාවක් කුමක්ද?", "අධික භක්තිය, විස්මය හෝ හදිසි බිය", "ගැඹුරු නින්ද", "කෑම ගැනීම", "ඇවිදීම", "ශරීරයේ ලොම් කෙළින් වීමෙන් අභ්‍යන්තර කම්පනය බාහිරට පෙන්වයි."),
        q("දෘෂ්ටි භේද අතරින් 'උල්ලෝකිත' දෘෂ්ටිය යොදා ගනු ලබන්නේ කුමන දිශාවක් බැලීමටද?", "ඉහළ අහස, දෙව්ලොව හෝ උස් කඳු මුදුන් දෙස බැලීමට", "පහළ පොළොව හා පාද දෙස බැලීමට", "වම් හා දකුණු පස පිටුපස බැලීමට", "ඇස් අඩක් වසා භාවනා ඉරියව්ව දැක්වීමට", "උසස් දෙයක් දෙස ඉහළ බැලීමට උල්ලෝකිත බැල්ම භාවිත කෙරේ."),
        q("දෘෂ්ටි භේද අතරින් 'අවලෝකිත' දෘෂ්ටියෙන් පෙන්නුම් කරන්නේ කුමන බැල්මක්ද?", "පහළට හෙවත් භූමිය දෙසට බැලීම (කල්පනාව, ලැජ්ජාව, දුක)", "ඉහළ අහස දෙස බැලීම", "වටේට කැරකී බැලීම", "ඇස් විශාල කර බිය ගැන්වීම", "පාද හා බිම දෙස බලන සෞම්‍ය ඉරියව්ව අවලෝකිත නම් වේ."),
        q("ශිරෝ භේද අතරින් 'පරාවෘත්ත' යනු හිස කුමන ආකාරයකින් හැරවීමද?", "මුහුණ සම්පූර්ණයෙන් පැත්තකට හෝ පසුපසට හරවා ඉවත බැලීම", "හිස කෙළින් තබා ගැනීම", "හිස ඉහළට එසවීම", "හිස ඉදිරියට වැනීම", "කෝපය, අමනාපය හෝ ලැජ්ජාවෙන් ඉවත බැලීම පරාවෘත්තයෙන් දැක්වේ."),
        q("නර්තනයේදී 'උත්ක්ෂිප්ත' ශිරෝ භේදය (හිස ඇල කොට ඉහළට හරවා තැබීම) පෙන්වන්නේ කුමක්ද?", "ආඩම්බර බව, විමසිල්ල හෝ 'ගන්න' යන ඉඟිය", "නින්දට වැටීම", "අමනාපයෙන් ඉවත යාම", "දුකින් ඇඬීම", "අභිනය දර්පණයේ දැක්වෙන මෙම හිස් චලනය රංගනය අලංකාර කරයි."),
        q("නව රස අතුරින් 'හාස්‍ය රසය' කොටස්වලට බෙදීමේදී පහත් නොවන මඳ සිනහව හඳුන්වන්නේ කුමන නමකින්ද?", "ස්මිත හෙවත් මඳ සිනහව", "අතිහාස්‍යය", "රෞද්‍ර කෝපය", "භයානක බිය", "උතුම් චරිත මුහුණෙන් දක්වන සංවර මඳ සිනහව ස්මිත හාස්‍යය නම් වේ."),
        q("'භීභත්ස රසය' සමඟ සෘජුව සම්බන්ධ වන ස්ථායී භාවය කුමක්ද?", "ජුගුප්සා (පිළිකුල)", "උත්සාහ", "රති", "විස්මය", "අපිරිසිදු හෝ අප්‍රසන්න දේ කෙරෙහි ඇති වන පිළිකුල් හැඟීම මෙයයි."),
        q("'ශාන්ත රසය' නව රස අතරට එකතු වීමට ප්‍රධාන වශයෙන් බලපෑ භාරතීය දාර්ශනික පසුබිම කුමක්ද?", "බෞද්ධ, ජෛන හා උපනිෂද් චින්තනයේ සන්සුන් බව", "භාරතීය යුද කලා හා සටන් සම්ප්‍රදාය", "පැරණි රාජ සභා විනෝද ක්‍රීඩා සම්ප්‍රදාය", "බටහිර නූතන වේදිකා නාට්‍ය ක්‍රමවේද", "අධ්‍යාත්මික සමාධිය හා මානසික ශාන්තිය උසස් රසයක් ලෙස පසුකාලීනව පිළිගැනිණි."),
        q("දේශීය උඩරට වන්නම් 18 අතුරින් 'විස්මය හා ප්‍රතාපය' (අද්භූත හා වීර රස) පෙනෙන වන්නමක් කුමක්ද?", "උදාර වන්නම හා තුරඟා වන්නම", "කළගෙඩි නැටුම", "ගොයම් නැටුම", "පොල් කෙළි නැටුම", "රජුන්ගේ තේජස හා අසාමාන්‍ය විස්මිත බව මෙම වන්නම්වල කවි හා චලනවලින් දිස්වේ."),
        q("උඩරට නැටුමේ 'හනුමා වන්නමේදී' නැට්ටුවා ප්‍රධාන වශයෙන් භාවිත කරන අභිනය කුමක්ද?", "වඳුරාගේ කඩිසර චලන හා හාස්‍ය අනුකරණය කරන ආංගික අභිනය", "පොතක් කියවන වාචික අභිනය", "කඳුළු සලන සාත්වික අභිනය", "වෙස්මුහුණු පැළඳීම", "වඳුරු චරිතයේ පැනීම් හා මුහුණු භාව හනුමා වන්නමේ විශේෂත්වයයි."),
        q("නර්තන කලාවේදී 'තාණ්ඩව' නර්තනය වඩාත් දියුණු ආකාරයෙන් දැකිය හැකි ඉන්දියානු දේව සංකල්පය කුමක්ද?", "නටරාජ (ශිව) දෙවියන්ගේ විශ්වීය නර්තනය", "ගණ දෙවියන්ගේ ගමන", "සරස්වතී දේවියගේ වීණා වාදනය", "ලක්ෂ්මී දේවියගේ නැටුම", "මැවීම, පැවැත්ම හා විනාශය ශිව තාණ්ඩවයෙන් සංකේතවත් කෙරේ."),
        q("ශ්‍රී ලංකාවේ 'ලාස්‍ය' නර්තන ශෛලියට වඩාත්ම උචිත දේශීය ජන නැටුම තෝරන්න.", "කළගෙඩි නැටුම සහ ගොයම් නැටුම", "සන්නි යකුමේ පිසාච නැටුම", "මහ සොහොන් සමයම", "හේවා කෝලම", "මෘදු, සෞම්‍ය හා කාන්තා ලාලිත්‍යය මෙම නැටුම්වලින් මතු වේ."),
        q("'අභිනය දර්පණය' කෘතියෙහි සඳහන් පරිදි නැට්ටුවෙකු සතු විය යුතු 'දශ ප්‍රාණ' හෝ ගුණාංග අතර වැදගත් වන්නේ කුමක්ද?", "තාල ඥානය, ප්‍රබල මතකය සහ අභිනය හැකියාව", "කෝපාවිෂ්ට වී වේගයෙන් රංගනය ඉදිරිපත් කිරීම", "තාලය නොසලකා හිතුමතේ චලන සිදු කිරීම", "සංගීත රිද්මයෙන් බැහැරව නිහඬව සිටීම", "ශාස්ත්‍රීය නැට්ටුවෙකු තුළ ශාරීරික හා මානසික සුදුසුකම් රැසක් තිබිය යුතුය."),
        q("නාට්‍ය ශාස්ත්‍රයේදී 'පාද භේද' හා 'චාරී' යනුවෙන් හඳුන්වන්නේ කුමන ශරීර අංගයේ චලනයන්ද?", "පාද සහ කලවා චලන රටා", "හිස සහ ඇස් චලන", "අත් සහ ඇඟිලි චලන", "තොල් සහ නාසය", "වේදිකාව මත ගමන් කිරීම හා පාද තැබීමේ විවිධ විධි මින් විස්තර කෙරේ."),
        q("නර්තනයකදී 'සාත්වික අභිනය' ප්‍රබලව පෙනෙන අවස්ථාවකට උදාහරණයක් කුමක්ද?", "ශෝකජනක කතා පුවතකදී නළුවාගේ ඇස්වල සැබෑ කඳුළු මතු වීම", "වෙස් තට්ටුව ඔප දැමීම", "බෙර වාදකයා තාලය වැඩි කිරීම", "විදුලි පහන් වර්ණ මාරු කිරීම", "හදවතින්ම චරිතයට පිවිසි විට පමණක් මෙවැනි ස්වාභාවික ප්‍රතිචාර හටගනී."),
        q("නව රස අතුරින් 'වීර රසය' කොටස් තුනකට බෙදා ඇත. ඒවා මොනවාද?", "දාන වීර, ධර්ම වීර සහ යුද්ධ වීර", "නෘත්ත, නෘත්‍ය සහ නාට්‍ය", "ආතත, විතත සහ ඝන", "විලම්බ, මධ්‍ය සහ ද්‍රුත", "පරිත්‍යාගශීලී බව, ධාර්මික බව හා රණකාමී බව වීර රසයේ ප්‍රභේද තුනයි."),
        q("'දයා වීර' හෙවත් කරුණාවෙන් යුත් වීරත්වයට අමතරව 'දාන වීර' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "සියලු සම්පත් පරිත්‍යාග කිරීමේදී පෙන්වන අභීත ධෛර්යය", "වෙස්මුහුණු සැඟවීම", "යුද්ධයෙන් පලා යාම", "නැටුම අතරමග නැවැත්වීම", "වෙස්සන්තර ජාතකය වැනි කථාවල දාන වීර රසය මැනවින් ප්‍රකට වේ."),
        q("'ආංගික අභිනය' සහ 'සාත්වික අභිනය' එකට බද්ධ වූ විට ප්‍රේක්ෂකයාට ලැබෙන අත්දැකීම කුමක්ද?", "චලන හුදු ව්‍යායාමයක් නොව සජීවී රංගනයක් වීම", "නැටුමේ රිද්ම රටා හා තාලය ව්‍යාකූල වීම", "පසුබිම් සංගීත හඬ හා ගායනය නොඇසී යාම", "වේදිකාවේ ආලෝකය හා දෘශ්‍ය බව හීන වීම", "ශරීර චලන සමඟ මානසික භාවය එක්වීම නර්තනයේ උසස්ම තත්ත්වයයි."),
        q("පහතරට 'කෝලම්' නාට්‍යයේ 'පොලිස් කෝලම' හෝ 'ජසයා ලෙන්චිනා' නරඹන විට ප්‍රධාන වශයෙන් උපදින රසය කුමක්ද?", "හාස්‍ය රසය", "කරුණා රසය", "ශාන්ත රසය", "භයානක රසය", "සමාජ දුර්වලතා උපහාසයට ලක් කිරීමෙන් ප්‍රේක්ෂකයාට සිනහව හා වින්දනය ගෙන දේ."),
        q("'භරත මුනිවරයාගේ' නාට්‍ය ශාස්ත්‍රය අනුව සියලුම රසයන් අතරින් ප්‍රධානම රස සතරක් 'මූලික රස' ලෙස සලකයි. ඒවා මොනවාද?", "ශෘංගාර, රෞද්‍ර, වීර සහ භීභත්ස", "ශාන්ත පමණක්", "කරුණා පමණක්", "අද්භූත පමණක්", "මෙම මූලික රස සතරින් අනෙක් රස හතර (හාස්‍ය, කරුණා, අද්භූත, භයානක) හටගන්නා බව කියැවේ."),
        q("නාට්‍ය ශාස්ත්‍ර සිද්ධාන්තය අනුව 'ශෘංගාර' රසය අනුකරණය කිරීමෙන් හෝ විකෘති වීමෙන් හටගන්නා රසය කුමක්ද?", "හාස්‍ය රසය", "කරුණා රසය", "භයානක රසය", "වීර රසය", "ශෘංගාරයෙන් හාස්‍යයත්, රෞද්‍රයෙන් කරුණාවත්, වීරයෙන් අද්භූතයත්, භීභත්සයෙන් භයානකත් උපදී."),
        q("නාට්‍ය ශාස්ත්‍රය අනුව 'රෞද්‍ර' රසයේ ක්‍රියාකාරිත්වයේ ප්‍රතිඵලයක් ලෙස උපදින රසය කුමක්ද?", "කරුණා රසය", "ශෘංගාර රසය", "හාස්‍ය රසය", "අද්භූත රසය", "විනාශකාරී කෝපයේ අවසන් ප්‍රතිඵලය ශෝකය හෙවත් කරුණා රසයයි."),
        q("නාට්‍ය ශාස්ත්‍රයට අනුව 'වීර' රසයේ ක්‍රියාකාරිත්වයෙන් උපදින රසය කුමක්ද?", "අද්භූත රසය", "භීභත්ස රසය", "කරුණා රසය", "භයානක රසය", "අසාමාන්‍ය වීර ක්‍රියාවන් දකින ප්‍රේක්ෂකයා තුළ විස්මය හෙවත් අද්භූත රසය උපදී."),
        q("'භීභත්ස' රසයේ ප්‍රතිඵලයක් ලෙස හටගන්නා අනෙක් රසය නාට්‍ය ශාස්ත්‍රය අනුව කුමක්ද?", "භයානක රසය", "ශෘංගාර රසය", "හාස්‍ය රසය", "ශාන්ත රසය", "භයංකර හා පිළිකුල් සහගත දර්ශන තුළින් බිය හෙවත් භයානක රසය හටගනී."),
        q("නර්තන රස වින්දනයේදී 'නරඹන්නා' තුළ පෙර අත්දැකීම් හා කලා රුචිකත්වය තිබීම වැදගත් වන්නේ ඇයි?", "නැටුමේ භාව හා සංකේත නිවැරදිව තේරුම් ගෙන රස විඳීමට (සහෘදභාවය)", "වේදිකාවේ වටිනාකම ගණන් හැදීමට", "ඇඳුම් මැසීමට", "බෙර අලුත්වැඩියා කිරීමට", "උසස් කලා කෘතියක් රස විඳීමට සහෘදයා තුළද යම් සංවේදී දැනුමක් තිබිය යුතුය."),
        q("දේශීය නර්තන අංගයක් වන 'කුවේණි අස්න' ඉදිරිපත් කිරීමේදී ගායකයා සහ නැට්ටුවා මතු කරන ප්‍රධාන රසය කුමක්ද?", "කරුණා රසය", "හාස්‍ය රසය", "ශෘංගාර රසය", "රෞද්‍ර රසය", "දරුවන් සමඟ වනයට පිටුවහල් කළ කුවේණියගේ දුක මෙහිදී හැඟීම්බරව ගැයේ."),
        q("ශරීරයේ 'අත්' චලනය කිරීමෙන් පමණක් නොව 'උරහිස් හා පපුව' චලනයෙන්ද ප්‍රකාශ වන්නේ කුමන අභිනයද?", "ආංගික අභිනය", "වාචික අභිනය", "ආහාර්ය අභිනය", "ලිඛිත අභිනය", "සම්පූර්ණ ශරීර චලන පද්ධතිය ආංගික අභිනය යටතට ගැනේ."),
        q("නාට්‍ය ශාස්ත්‍රයේදී 'සාත්වික' යන වචනයේ මූලික අර්ථය වන 'සත්ත්ව' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "මනසේ ඒකාග්‍රතාව හා හදවතේ උපදින සැබෑ චිත්ත ශක්තිය", "රංග වේදිකාවේ පසුබිම් තිරය හා විදුලි ආලෝක පද්ධතිය", "වෙස්මුහුණු කැපීමට ගන්නා සැහැල්ලු වෙල් කදුරු ලී කැබලි", "සාම්ප්‍රදායික වෙස් ඇඳුමේ පබළු මාල හා රිදී රංග වස්ත්‍ර", "අවධානය යොමු වූ පවිත්‍ර මනස සත්ත්ව ලෙස සලකන අතර එයින් සාත්වික අභිනය උපදී."),
        q("දේශීය නර්තනයේ 'වේස් තට්ටුව' හා 'තෝඩු' පැළඳීමෙන් නැට්ටුවාට ලැබෙන ගාම්භීර පෙනුම අයත් වන්නේ කුමන අභිනයටද?", "ආහාර්ය අභිනයට", "වාචික අභිනයට", "සාත්වික අභිනයට", "ආංගික අභිනයට", "රංග ආභරණ හා වස්ත්‍ර ශිල්පියාගේ පෞරුෂය ඉස්මතු කරන ආහාර්ය අංග වේ."),
        q("නර්තනයකදී 'තොල් සහ නිකට' වැනි උපාංග වෙව්ලවමින් අභිනය දැක්වීමෙන් ප්‍රකාශ කළ හැකි හැඟීම කුමක්ද?", "අධික ශීතල, බිය හෝ තදබල ශෝකය", "සන්සුන් නින්ද", "සාමාන්‍ය සිනහව", "භාවනාව", "මුහුණේ කුඩා උපාංගවල චලන ප්‍රේක්ෂකයාට සමීපව හැඟීම් දැනවීමට උපකාරී වේ."),
        q("ශ්‍රී ලාංකේය 'මුද්‍රා නාට්‍ය' කලාවේ (උදා කරදිය, නල දමයන්ති) බොහෝ විට ඉවත් කර ඇති අභිනය කුමක්ද?", "වාචික අභිනය (සජීවී දෙබස් කීම)", "ආංගික අභිනය", "ආහාර්ය අභිනය", "සාත්වික අභිනය", "පසුබිම් සංගීතය හා චලන පමණක් යොදාගෙන මුද්‍රා නාට්‍යයේ කතාව ඉදිරිපත් කෙරේ."),
        q("භරත නාට්‍යම් හෝ කථකලි වැනි නර්තනයකදී 'මුහුණේ වර්ණ ආලේපනය' ඉතා තදින් සිදු කරන්නේ කුමන අභිනය ශක්තිමත් කිරීමටද?", "ආහාර්ය අභිනය", "වාචික අභිනය", "ආංගික අභිනය", "තාල අභිනය", "විශාල රංග ශාලාවක පසුපස සිටින ප්‍රේක්ෂකයාට පවා ඉරියව් පැහැදිලිව පෙනීමට මෙය උදව් වේ."),
        q("ග්‍රීවා භේද අතරින් 'සුන්දරී' බෙල්ල චලනය පුහුණු වීමේදී නැට්ටුවා සැලකිලිමත් විය යුත්තේ කුමකටද?", "උරහිස් නොසොල්වා බෙල්ල පමණක් තිරස්ව ගෙන යාම", "උරහිස් දෙකම ඉහළට ඔසවා තබා ගැනීම", "කඳ සම්පූර්ණයෙන් පසුපසට නවා තැබීම", "දෑස් පියාගෙන හිස පහළට බර කර ගැනීම", "උරහිස් නිශ්චලව තබා බෙල්ල ලිස්සවීම සුන්දරී භේදයේ නිවැරදි තාක්ෂණයයි."),
        q("දෘෂ්ටි භේද අතරින් 'සාචි' බැල්ම යොදාගෙන රඟ දක්වන නර්තන අවස්ථාවක් නම් කරන්න.", "ලැජ්ජාවෙන් යුත් පෙම්වතියකගේ චරිතය හෝ සැක සහිත විමසීම", "රණකාමී යුද සටනක්", "නිදා සිටින අවස්ථාවක්", "අහස දෙස බලන අවස්ථාවක්", "ඇස් කොණින් බැලීම නෘත්‍ය අංගවල බහුලව භාවිත වන සියුම් අභිනයකි."),
        q("නව රස අතුරින් 'විස්මය' ප්‍රධාන ස්ථායී භාවය වන රසය හඳුන්වන්නේ කුමන නමකින්ද?", "අද්භූත රසය", "රෞද්‍ර රසය", "කරුණා රසය", "භීභත්ස රසය", "අසාමාන්‍ය හා චමත්කාරජනක සිදුවීම්වලදී අද්භූත රසය උපදී."),
        q("නර්තන විචාරයේදී 'රස භංගය' යනුවෙන් හඳුන්වන්නේ කුමන දුර්වලතාවක්ද?", "රංගනයේ අභිනය, තාලය හෝ ඇඳුම් නොගැළපී රස වින්දනයට බාධා වීම", "රසය උපරිමයට පත් වීම", "ප්‍රේක්ෂකයන් අත්පුඩි ගැසීම", "තාලම්පට වාදනය සාර්ථක වීම", "අනවශ්‍ය අතිශයෝක්තිය හෝ තාල දෝෂ නිසා රස භංගය සිදු විය හැකිය."),
        q("උඩරට නැටුමේදී 'ගජගා වන්නම' නටන නැට්ටුවා ඇතාගේ ගමන නිරූපණය කරන්නේ කුමන අභිනය ප්‍රධාන කොටගෙනද?", "ආංගික අභිනය (සමබර පාද චලන හා හස්ත මුද්‍රා)", "වාචික අභිනය පමණක්", "සාත්වික අභිනය පමණක්", "ආහාර්ය අභිනය පමණක්", "ඇතාගේ ගාම්භීර ගමන හා සොඬය වැනීම ආංගික අභිනයෙන් අපූරුවට පෙන්වයි."),
        q("නාට්‍ය ශාස්ත්‍රයේදී 'අනුභාව' යන කොටසට අයත් වන්නේ කුමක්ද?", "හැඟීමක් ඇති වූ පසු ශරීරයෙන් පෙන්වන ඉරියව්", "වේදිකාවේ පසුබිම් තිරයේ ප්‍රධාන වර්ණය", "ප්‍රේක්ෂක ශාලාවේ වාස්තු විද්‍යා සැකැස්ම", "වාද්‍ය භාණ්ඩයේ වරපටි බැඳීමේ ක්‍රමවේදය", "අභ්‍යන්තර හැඟීම බාහිරට දැනෙන සේ ප්‍රකාශ වන සියලු ලක්ෂණ අනුභාව වේ."),
        q("නර්තනයේදී 'චතුර්විධ අභිනය' සමබරව ප්‍රගුණ කළ ශිල්පියෙකු හඳුන්වනු ලබන්නේ කෙසේද?", "පරිපූර්ණ රංගධරයෙකු හෙවත් දක්ෂ නර්තන ශිල්පියෙකු ලෙස", "බෙර කඳන් කපා සකස් කරන වඩු ශිල්පියෙකු ලෙස", "වේදිකා පසුතල සැරසිලි නිර්මාණකරුවෙකු ලෙස", "තාලම්පට වාදනය පමණක් කරන සහායකයෙකු ලෙස", "අභිනයන් හතරේම මනා සුසංයෝගය ශ්‍රේෂ්ඨ කලාකරුවෙකු බිහි කරයි."),
        q("නව රස අතර 'ශෘංගාර, හාස්‍ය, කරුණා' යන රසයන් තුනට වඩාත් උචිත ලය මට්ටම් මොනවාද?", "මධ්‍ය සහ විලම්බ ලය", "අතිශය ද්‍රුත ලය පමණක්", "තාල රහිත බව", "වේගවත් කෑගැසීම", "සෞම්‍ය හා සංවේදී හැඟීම් ප්‍රකාශ කිරීමට සුමට ලය උපකාරී වේ."),
        q("පාසල් නර්තන තරගයකදී විනිශ්චය මණ්ඩලය 'භාව ප්‍රකාශනය' සඳහා ලකුණු දීමේදී ප්‍රධාන වශයෙන් බලන්නේ කුමක්ද?", "මුහුණු ඉරියව්, දෘෂ්ටිය හා මුද්‍රා තේමාවට ගැළපීම", "නැට්ටුවාගේ උස හා ශරීර බර පිළිබඳ මිනුම", "වේදිකා ඇඳුමේ වර්ණය හා මිල ගණන් පමණක්", "වේදිකාවේ දිග හා පළල පිළිබඳ මිනුම පමණක්", "තාක්ෂණික පියවර සමඟ සාර්ථක අභිනය තිබීම ජයග්‍රහණයට අත්‍යවශ්‍ය වේ."),
        q("O/L නර්තන විෂය මාලාවට 'නාට්‍ය ශාස්ත්‍රය' හා 'අභිනය' ඇතුළත් කිරීමෙන් සිසුන් ලබන ප්‍රධානම කුසලතාව කුමක්ද?", "දේශීය හා පෙරදිග නර්තනය ශාස්ත්‍රීයව විග්‍රහ කිරීම", "සියලු නැටුම් සඳහා එක් තනි තාලයක් භාවිත කිරීම", "වෙස්මුහුණු කැපීමේ වඩු කාර්මික පුහුණුව ලැබීම", "ශාන්තිකර්ම මඩු සැරසිලි ව්‍යාපාරයක් ඇරඹීම", "ශාස්ත්‍රීය පදනම අවබෝධ කර ගැනීම නර්තන කලාව උසස් තලයකට ඔසවා තබයි.")
    )
}
